-- Exam attempts are separate from mutable learning history and staff-issued credentials.
begin;
create table abbate_private.exam_bank (
 id text primary key, course text not null, content jsonb not null
);
alter table abbate_private.exam_bank enable row level security;
revoke all on abbate_private.exam_bank from public,anon,authenticated;
insert into abbate_private.exam_bank(id,course,content)
select q->>'id',q->>'course',q from jsonb_array_elements($exam_bank$[{"id":"g-flurpruefung","course":"gabelstapler","title":"Was gehört zu einer Sicht- und Funktionsprüfung vor Arbeitsbeginn?","context":"Vor dem ersten Einsatz des Tages.","answers":["Nur Kraftstoffstand und Fahrzeugfarbe prüfen.","Bremsen, Lenkung, Gabeln, Reifen und Sicherheitseinrichtungen nach Betriebsanleitung prüfen.","Eine Probefahrt mit angehobener Last durchführen."],"correct":1},{"id":"g-rueckhalt","course":"gabelstapler","title":"Wie gehst du mit dem vorhandenen Fahrerrückhaltesystem um?","context":"Der Stapler verfügt über ein vorgeschriebenes Rückhaltesystem.","answers":["Es während der Fahrt ordnungsgemäß benutzen.","Nur auf unebenen Böden benutzen.","Es bei kurzen Fahrten außer Betrieb setzen."],"correct":0},{"id":"g-mangelmelden","course":"gabelstapler","title":"Was gilt für einen Stapler mit beschädigter Gabelzinke?","context":"Bei der Prüfung bemerkst du eine deutlich verbogene Zinke.","answers":["Die Last möglichst auf die andere Zinke verteilen.","Bis zur nächsten Wartung ausschließlich leichte Lasten fahren.","Stapler nicht einsetzen und den Mangel der zuständigen Person melden."],"correct":2},{"id":"g-einweisung","course":"gabelstapler","title":"Du wechselst auf einen Stapler mit anderer Bedienung. Was ist vor dem Einsatz erforderlich?","context":"Die Bedienung weicht von deinem bisherigen Fahrzeug ab.","answers":["Eine gerätebezogene Einweisung und die Beachtung der Betriebsanleitung.","Eine kurze Erklärung durch einen unbeteiligten Kollegen genügt immer.","Keine zusätzliche Information, wenn du einen Staplerschein besitzt."],"correct":0},{"id":"g-anbaugeraet","course":"gabelstapler","title":"Du sollst ein Anbaugerät verwenden. Was prüfst du zuerst?","context":"Ein neues Arbeitsgerät verändert die Lastaufnahme.","answers":["Ob das Anbaugerät zur Fahrzeugfreigabe und zur zulässigen Belastung passt.","Nur, ob sich das Gerät optisch befestigen lässt.","Ob das Anbaugerät ohne Dokumentation montiert werden kann."],"correct":0},{"id":"g-diagramm","course":"gabelstapler","title":"Wofür benötigst du das Tragfähigkeitsdiagramm?","context":"Eine schwere Last liegt mit weit außen liegendem Schwerpunkt vor.","answers":["Um den kürzesten Fahrweg festzulegen.","Um die maximal zulässige Last in Abhängigkeit von Hubhöhe und Lastschwerpunkt zu beurteilen.","Um die Tankfüllmenge zu bestimmen."],"correct":1},{"id":"g-lastschwerpunkt","course":"gabelstapler","title":"Was passiert typischerweise, wenn der Lastschwerpunkt weiter nach vorn rückt?","context":"Eine lange Last ragt weit vor die Gabelzinken.","answers":["Die zulässige Tragfähigkeit kann sinken.","Die Tragfähigkeit steigt immer.","Der Abstand hat keinen Einfluss auf das Kippmoment."],"correct":0},{"id":"g-gabelabstand","course":"gabelstapler","title":"Wie sollen die Gabelzinken eine passende Palette aufnehmen?","context":"Du willst eine gleichmäßig beladene Palette aufnehmen.","answers":["Mit möglichst engem Zinkenabstand und nur an einer Ecke.","Mit so großem Abstand, dass die Palette seitlich überkippt.","Mit geeignetem Zinkenabstand und ausreichender Unterfahr- und Auflagefläche."],"correct":2},{"id":"g-schieflast","course":"gabelstapler","title":"Eine Last ist instabil gestapelt. Was ist richtig?","context":"Kartons können beim Anheben herunterfallen.","answers":["Langsam anfahren; die Ladung stabilisiert sich selbst.","Last vor der Aufnahme ausreichend sichern oder neu zusammenstellen lassen.","Last über Kopfhöhe anheben, damit sie nicht stört."],"correct":1},{"id":"g-personen","course":"gabelstapler","title":"Darf eine Person auf gewöhnlichen Gabelzinken angehoben werden?","context":"Ein Kollege möchte eine Leuchte erreichen.","answers":["Ja, wenn der Kollege einen Helm trägt.","Nein, für Personen sind nur dafür vorgesehene und zulässige Einrichtungen nach besonderen Vorgaben nutzbar.","Ja, wenn nur eine geringe Höhe angefahren wird."],"correct":1},{"id":"g-transporthoehe","course":"gabelstapler","title":"Wie transportierst du eine Palette üblicherweise?","context":"Der Fahrweg ist frei und eben.","answers":["Mit nur so weit wie nötig angehobener Last und gemäß Betriebsanleitung.","Mit möglichst hoch gehobener Last, um besser gesehen zu werden.","Mit stark nach vorn geneigtem Hubmast unabhängig von der Last."],"correct":0},{"id":"g-kurvenfahrt","course":"gabelstapler","title":"Warum ist zügiges Kurvenfahren mit dem Stapler gefährlich?","context":"Du möchtest einen engen Weg schnell verlassen.","answers":["Weil nur die Batterie schneller entladen wird.","Weil der Stapler dadurch automatisch besser lenkt.","Weil seitliche Kräfte die Standsicherheit beeinträchtigen und zum Umkippen führen können."],"correct":2},{"id":"g-ladebruecke","course":"gabelstapler","title":"Was kontrollierst du vor dem Befahren einer Ladebrücke?","context":"Du sollst in einen Lkw fahren.","answers":["Nur, ob der Weg breit genug aussieht.","Tragfähigkeit, sichere Auflage und Sicherung gegen Verschieben sowie die Sicherung des Fahrzeugs.","Nur, ob die Beleuchtung eingeschaltet ist."],"correct":1},{"id":"g-fussgaenger","course":"gabelstapler","title":"Wie verhältst du dich an einem unübersichtlichen Kreuzungsbereich mit Fußgängern?","context":"Sichtbeziehungen sind eingeschränkt.","answers":["Mit angepasster Geschwindigkeit fahren, erforderlichenfalls anhalten und für sichere Sicht sorgen.","Stets Vorfahrt beanspruchen, wenn du eine Last trägst.","Ausschließlich hupen und weiterfahren."],"correct":0},{"id":"g-batterieladen","course":"gabelstapler","title":"Was ist beim Laden einer Antriebsbatterie besonders zu beachten?","context":"Es wird ein Batterieladeplatz genutzt.","answers":["Der Ladeplatz kann ohne Rücksicht auf Herstellerhinweise ausgewählt werden.","Offene Flammen sind zulässig, solange der Stapler steht.","Geeigneter Ladebereich, ausreichende Lüftung und Vorgaben des Herstellers sowie zum Brand- und Explosionsschutz."],"correct":2},{"id":"h-beauftragt","course":"hebebuehnen","title":"Unter welcher Voraussetzung darfst du eine Hubarbeitsbühne selbstständig bedienen?","context":"Du sollst eine Arbeitsbühne im Betrieb einsetzen.","answers":["Wenn du einen Pkw-Führerschein besitzt.","Wenn du geeignet, unterwiesen bzw. qualifiziert und vom Arbeitgeber beauftragt bist.","Wenn du eine Arbeitsbühne schon einmal gesehen hast."],"correct":1},{"id":"h-vorpruefung","course":"hebebuehnen","title":"Was ist vor Beginn der Arbeit mit der Hubarbeitsbühne zu prüfen?","context":"Die Bühne stand über Nacht im Freien.","answers":["Sicht- und Funktionsprüfung nach Herstellerangaben einschließlich Sicherheitseinrichtungen.","Nur die Farbe und das Alter der Bühne.","Ob das Arbeitsmaterial bereits auf der Plattform liegt."],"correct":0},{"id":"h-tragfaehigkeit","course":"hebebuehnen","title":"Welche Angaben bestimmen die zulässige Belastung des Arbeitskorbs?","context":"Zwei Personen möchten zusätzlich Werkzeug mitnehmen.","answers":["Die Personen dürfen das zulässige Gesamtgewicht frei schätzen.","Nur das Gewicht der schwersten Person zählt.","Die Tragfähigkeitsangabe für Personen, Werkzeuge und Material darf nicht überschritten werden."],"correct":2},{"id":"h-untergrund","course":"hebebuehnen","title":"Worauf achtest du vor dem Aufstellen einer Bühne mit Abstützungen?","context":"Du arbeitest nahe einer aufgefüllten Fläche.","answers":["Nur auf die Reichweite des Auslegers.","Auf Tragfähigkeit und Ebenheit des Untergrunds sowie auf geeignete Abstützung nach Anleitung.","Auf eine möglichst geringe Zahl ausgefahrener Stützen."],"correct":1},{"id":"h-wind","course":"hebebuehnen","title":"Starker Wind setzt ein. Wie gehst du vor?","context":"Du befindest dich mit einer Bühne im Freien.","answers":["Herstellergrenzen beachten und bei Überschreitung den Betrieb einstellen beziehungsweise den Korb sicher absenken.","Die Bühne möglichst weit ausfahren, damit sie stabiler steht.","Nur dann reagieren, wenn lose Gegenstände herunterfallen."],"correct":0},{"id":"h-strom","course":"hebebuehnen","title":"Du musst in der Nähe einer Freileitung arbeiten. Was ist entscheidend?","context":"Eine spannungsführende Leitung liegt im Arbeitsbereich.","answers":["Ein Helm ersetzt die Einhaltung des Sicherheitsabstands.","Nur den Korb isolieren und ohne Abstimmung arbeiten.","Gefahrenbereich klären und notwendige Schutzabstände oder andere geeignete Maßnahmen sicherstellen."],"correct":2},{"id":"h-notablass","course":"hebebuehnen","title":"Warum muss das Verfahren für den Notablass bekannt sein?","context":"Ein Ausfall der normalen Steuerung ist möglich.","answers":["Damit bei einer Störung eine sichere Rettung entsprechend dem Gerät möglich ist.","Damit das Gerät schneller im normalen Betrieb fährt.","Um die regelmäßige Prüfung zu ersetzen."],"correct":0},{"id":"h-gelaender","course":"hebebuehnen","title":"Wie erreichst du zusätzliche Höhe im Arbeitskorb?","context":"Ein Montagepunkt liegt knapp über deiner Reichweite.","answers":["Auf die Korbumwehrung steigen.","Ein Brett auf das Geländer legen.","Eine geeignete Bühne mit ausreichender Arbeitshöhe einsetzen; nicht auf Geländer steigen."],"correct":2},{"id":"h-psaga","course":"hebebuehnen","title":"Welche Vorgaben gelten für persönliche Absturzschutzausrüstung?","context":"Du nutzt eine Arbeitsbühne, für die ein Rückhaltesystem vorgesehen ist.","answers":["Ein beliebiger Anschlagpunkt außerhalb des Korbs reicht immer.","Gefährdungsbeurteilung, Herstellerangaben und geeignete Anschlagpunkte beachten.","Auf jede Sicherung verzichten, wenn der Korb ein Geländer besitzt."],"correct":1},{"id":"h-verfahren","course":"hebebuehnen","title":"Darf die Bühne mit angehobener Plattform verfahren werden?","context":"Die Arbeitsstelle liegt wenige Meter weiter.","answers":["Nur wenn das Modell und die Einsatzbedingungen es nach Herstellerangaben zulassen.","Immer, solange alle Personen sich festhalten.","Nein, unabhängig von Bauart und Herstellerfreigabe niemals."],"correct":0},{"id":"h-kollision","course":"hebebuehnen","title":"Was ist bei Arbeiten nahe Kranen oder anderen Maschinen zu organisieren?","context":"Bewegte Teile könnten den Arbeitskorb erreichen.","answers":["Nichts; der Arbeitskorb ist immer sichtbar.","Den Arbeitskorb grundsätzlich über die anderen Maschinen fahren.","Arbeitsbereiche koordinieren, damit keine Kollision oder Quetschstelle entsteht."],"correct":2},{"id":"h-einstieg","course":"hebebuehnen","title":"Wie erfolgt das Betreten oder Verlassen des Arbeitskorbs?","context":"Du erreichst den Korb auf Bodenhöhe.","answers":["Über das Außengeländer klettern.","Über den vorgesehenen Zugang bei sicherer Stellung gemäß Betriebsanleitung.","Über eine daneben gestellte Leiter bei ausgefahrenem Ausleger."],"correct":1},{"id":"h-defekt","course":"hebebuehnen","title":"Die Not-Aus-Einrichtung funktioniert nicht. Was tust du?","context":"Bei der Prüfung stellst du den Mangel fest.","answers":["Die Bühne nicht einsetzen und den Mangel melden.","Weiterarbeiten, wenn die normale Steuerung funktioniert.","Den Schalter abkleben, damit niemand ihn betätigt."],"correct":0},{"id":"h-sicht","course":"hebebuehnen","title":"Die Fahrbewegung ist wegen eines Hindernisses nicht einsehbar. Wie gehst du vor?","context":"Du sollst eine fahrbare Bühne versetzen.","answers":["Ohne Sicht langsam weiterfahren.","Nur auf den Abstandsanzeiger verlassen.","Bewegung stoppen und Sicht oder sichere Einweisung nach Betriebsanweisung sicherstellen."],"correct":2},{"id":"h-rettung","course":"hebebuehnen","title":"Was gehört zur Einsatzplanung bei Arbeiten in größerer Höhe?","context":"Die Bühne wird in einem abgelegenen Bereich eingesetzt.","answers":["Nur die geplante Arbeitsdauer.","Ein geeignetes Rettungskonzept mit erreichbaren, eingewiesenen Personen und Notablassverfahren.","Die Annahme, dass die Feuerwehr jede Störung sofort lösen wird."],"correct":1},{"id":"k-befaehigung","course":"krane","title":"Was ist für das selbstständige Führen eines Krans erforderlich?","context":"Ein neuer Mitarbeiter soll Kranarbeiten übernehmen.","answers":["Eignung und erforderliche Qualifikation, Einweisung sowie entsprechende Beauftragung.","Ein Pkw-Führerschein reicht aus.","Einmaliges Zuschauen genügt."],"correct":0},{"id":"k-funktionspruefung","course":"krane","title":"Was gehört vor Schichtbeginn zur Kontrolle des Krans?","context":"Du übernimmst einen Hallenkran.","answers":["Nur die Laufzeit auf dem Typenschild ablesen.","Sicherheitsrelevante Funktionen und sichtbare Mängel nach Betriebsanleitung kontrollieren.","Den Kran ohne Kontrolle mit maximaler Last testen."],"correct":1},{"id":"k-traglast","course":"krane","title":"Welche Bedeutung hat die zulässige Tragfähigkeit?","context":"Eine Last soll angehoben werden.","answers":["Sie ist eine unverbindliche Empfehlung.","Sie gilt nur bei vollständig eingefahrenem Haken.","Die für den jeweiligen Betriebszustand zulässige Tragfähigkeit darf nicht überschritten werden."],"correct":2},{"id":"k-personen","course":"krane","title":"Was gilt für Personen unter schwebenden Lasten?","context":"Die Last wird über einen Arbeitsbereich bewegt.","answers":["Der Gefahrenbereich ist freizuhalten; niemand darf unter die schwebende Last treten.","Ein Helm erlaubt den Aufenthalt direkt darunter.","Kurzes Unterqueren ist zulässig, wenn der Kran langsam fährt."],"correct":0},{"id":"k-signale","course":"krane","title":"Du kannst den Anschläger nicht sehen und erhältst widersprüchliche Signale. Was tust du?","context":"Die Verständigung ist unklar.","answers":["Den letzten Fahrbefehl fortsetzen.","Die Bewegung stoppen und die Verständigung eindeutig klären.","Die Last schneller absetzen, ohne Rücksprache."],"correct":1},{"id":"k-sicht","course":"krane","title":"Wer unterstützt beim Transport, wenn der Kranführer den Lastweg nicht vollständig einsehen kann?","context":"Ein Hallenpfeiler verdeckt den Weg.","answers":["Eine zufällig vorbeigehende Person ohne Absprache.","Niemand; nur der Haken ist entscheidend.","Eine geeignete, eingewiesene Person mit eindeutig vereinbarter Verständigung."],"correct":2},{"id":"k-ruck","course":"krane","title":"Warum sind ruckartige Kranbewegungen zu vermeiden?","context":"Eine schwere Last beginnt zu pendeln.","answers":["Sie erzeugen zusätzliche dynamische Beanspruchungen und können die Last destabilisieren.","Sie vermindern grundsätzlich jede Pendelbewegung.","Sie erhöhen stets die Nenntragfähigkeit."],"correct":0},{"id":"k-sperrbereich","course":"krane","title":"Was ist vor dem Schwenken einer Last in einem gemeinsam genutzten Bereich zu prüfen?","context":"Andere Beschäftigte arbeiten in der Nähe.","answers":["Ob die Last optisch zum Kran passt.","Ob der Gefahrenbereich gesichert ist und keine Personen gefährdet werden.","Ob die Last möglichst hoch über allen Personen geführt werden kann."],"correct":1},{"id":"k-stuetzen","course":"krane","title":"Was ist bei einem Mobilkran mit Abstützungen entscheidend?","context":"Ein Kran wird auf teilweise aufgefülltem Boden aufgestellt.","answers":["Nur die Breite der Fahrbahn.","Die Farbe der Abstützteller.","Tragfähiger Untergrund sowie Abstützung und Lastverteilung nach Aufstell- und Herstellerangaben."],"correct":2},{"id":"k-wetter","course":"krane","title":"Eine Windböe bringt die Last stark ins Pendeln. Was ist richtig?","context":"Du arbeitest im Freien.","answers":["Bewegung sicher anhalten und zulässige Einsatzbedingungen beachten.","Die Bewegung ruckartig beschleunigen.","Die Last trotz Überschreitung der Herstellergrenzen weiterheben."],"correct":0},{"id":"k-freileitung","course":"krane","title":"Was gilt beim Kraneinsatz in der Nähe elektrischer Freileitungen?","context":"Ausleger oder Last könnten sich der Leitung nähern.","answers":["Mit einer nichtleitenden Last sind Abstände unwichtig.","Gefahrenbereich und erforderliche Schutzmaßnahmen vor Arbeitsbeginn mit den Verantwortlichen klären.","Den Kranführer nur auf die eigene Reaktion verlassen."],"correct":1},{"id":"k-sichern","course":"krane","title":"Was machst du, bevor du den Kran verlässt?","context":"Die Arbeit wird unterbrochen.","answers":["Die Last schwebend hängen lassen.","Den Kran mit laufendem Antrieb unbeaufsichtigt stehen lassen.","Last sicher absetzen und den Kran gemäß Betriebsanleitung sichern."],"correct":2},{"id":"k-lastanschlag","course":"krane","title":"Woran erkennst du, ob das verwendete Anschlagmittel geeignet ist?","context":"Die Last soll mit einem Hebeband gehoben werden.","answers":["An Kennzeichnung, Tragfähigkeit, Zustand und Eignung für die Anschlagart.","Allein an der Farbe des Hebebandes.","Daran, dass es bereits gestern verwendet wurde."],"correct":0},{"id":"k-stopp","course":"krane","title":"Eine Person betritt unerwartet den Lastweg. Was tust du?","context":"Der Kran bewegt gerade eine Last.","answers":["Die Bewegung unverzüglich sicher stoppen und den Gefahrenbereich räumen lassen.","Nur ein Warnsignal geben und weiterfahren.","Die Last höher anheben und darüber hinwegfahren."],"correct":0},{"id":"k-neuerkran","course":"krane","title":"Du erhältst einen Kran mit einer unbekannten Steuerung. Was ist richtig?","context":"Die Bedienelemente sind anders als bisher.","answers":["Die üblichen Tasten auf Verdacht ausprobieren.","Eine andere Person ohne Ausbildung vorfahren lassen.","Vor dem selbstständigen Einsatz die erforderliche gerätebezogene Einweisung erhalten."],"correct":2},{"id":"a-kennzeichnung","course":"lasten","title":"Woran erkennst du die zulässige Belastbarkeit eines Anschlagmittels?","context":"Du möchtest ein Anschlagmittel auswählen.","answers":["Am Materialgeruch.","An der geeigneten, lesbaren Tragfähigkeitskennzeichnung und Herstellerangabe.","An der Länge der Lagerzeit."],"correct":1},{"id":"a-sichtpruefung","course":"lasten","title":"Du bemerkst einen deutlichen Schnitt im Hebeband. Wie gehst du vor?","context":"Das Band soll eine Last tragen.","answers":["Das Band nicht verwenden und der Prüfung bzw. Aussonderung zuführen.","Den Schnitt mit Klebeband abdecken.","Es nur für besonders leichte Lasten verwenden."],"correct":0},{"id":"a-neigungswinkel","course":"lasten","title":"Was passiert bei größerem Neigungswinkel der Anschlagstränge zur Senkrechten?","context":"Ein zweisträngiges Gehänge spreizt sich stärker.","answers":["Die Strangkräfte sinken immer.","Die Strangkräfte bleiben gleich.","Die Kräfte in den Strängen steigen; zulässige Winkel und Tragfähigkeiten sind einzuhalten."],"correct":2},{"id":"a-schwerpunkt","course":"lasten","title":"Warum musst du den Schwerpunkt der Last kennen?","context":"Die Last ist ungleichmäßig aufgebaut.","answers":["Damit die Last beim Anheben stabil bleibt und nicht unkontrolliert kippt.","Um die Farbe der Anschlagmittel auszuwählen.","Damit die Last schneller gedreht werden kann."],"correct":0},{"id":"a-kantenschutz","course":"lasten","title":"Ein Hebeband liegt an einer scharfen Bauteilkante an. Was ist zu tun?","context":"Das Bauteil soll angehoben werden.","answers":["Die Last schnell anheben, bevor das Band beschädigt wird.","Geeigneten Kantenschutz verwenden und Anschlagart prüfen.","Nur die Lastfläche mit einem Tuch reinigen."],"correct":1},{"id":"a-haken","course":"lasten","title":"Was beachtest du beim Einhängen eines Anschlagmittels?","context":"Du benutzt einen Lasthaken.","answers":["Das Anschlagmittel seitlich auf die Hakenspitze legen.","Die Sicherungsklappe dauerhaft offenhalten.","Den Haken bestimmungsgemäß im Hakengrund belasten und Sicherungseinrichtungen beachten."],"correct":2},{"id":"a-knoten","course":"lasten","title":"Darfst du ein zu langes Hebeband mit einem Knoten verkürzen?","context":"Die Anschlaglänge passt nicht.","answers":["Nein; nur eine geeignete, zugelassene Anschlagart oder passendes Anschlagmittel verwenden.","Ja, wenn der Knoten sehr fest gezogen wird.","Ja, sofern die Last im Moment stillsteht."],"correct":0},{"id":"a-probehub","course":"lasten","title":"Warum wird eine Last zunächst vorsichtig angehoben?","context":"Du möchtest sicher transportieren.","answers":["Damit sie möglichst schnell pendelt.","Um Sitz der Anschlagmittel, Stabilität und Schwerpunktlage zu kontrollieren.","Weil sich die Tragfähigkeit dabei automatisch erhöht."],"correct":1},{"id":"a-lastweg","course":"lasten","title":"Wo dürfen sich Personen während des Lasttransports aufhalten?","context":"Die Last wird mit einem Kran verfahren.","answers":["Direkt unter der Last mit Schutzhelm.","Auf der Last, wenn sie festhalten können.","Außerhalb des Gefahrenbereichs und nicht unter schwebenden Lasten."],"correct":2},{"id":"a-haende","course":"lasten","title":"Wie vermeidest du Quetschverletzungen beim Absetzen?","context":"Die Last nähert sich der Auflagefläche.","answers":["Hände und Füße aus dem Quetschbereich halten und geeignete Hilfsmittel verwenden.","Die Last mit der bloßen Hand unterfassen.","Zwischen Last und Wand stehen, um die Lage zu korrigieren."],"correct":0},{"id":"a-vierstraenge","course":"lasten","title":"Was gilt für die Lastverteilung bei einem viersträngigen Gehänge ohne Lastausgleich?","context":"Eine starre Last wird angeschlagen.","answers":["Alle vier Stränge tragen zwangsläufig gleich viel.","Ohne Nachweis der gleichmäßigen Verteilung darf die Tragfähigkeit nicht pauschal für vier gleich belastete Stränge angesetzt werden.","Der Neigungswinkel ist dann unerheblich."],"correct":1},{"id":"a-chemikalien","course":"lasten","title":"Was gilt beim Einsatz textiler Anschlagmittel in Kontakt mit Chemikalien?","context":"Du arbeitest mit einer unbekannten Flüssigkeit.","answers":["Die Farbe des Bands zeigt zuverlässig die Beständigkeit.","Jedes textile Band ist gegen alle Chemikalien beständig.","Beständigkeit und Herstellerangaben prüfen; ungeeignete Mittel nicht verwenden."],"correct":2},{"id":"a-aufbewahrung","course":"lasten","title":"Wie werden Anschlagmittel nach dem Gebrauch gelagert?","context":"Der Einsatz ist beendet.","answers":["Sauber, trocken und vor Beschädigung geschützt nach Herstellervorgaben.","Unter einer ungeschützten Last am Boden eingeklemmt.","An einem beliebigen scharfen Haken im Freien."],"correct":0},{"id":"a-auswahl","course":"lasten","title":"Was ist bei empfindlichen oder scharfkantigen Lasten besonders zu berücksichtigen?","context":"Eine lackierte Maschinenkomponente soll bewegt werden.","answers":["Nur die Transportgeschwindigkeit.","Geeignete Anschlagmittel und Schutzmaßnahmen für Lastoberfläche und Kanten.","Unabhängig von der Last immer das gleiche Stahlseil."],"correct":1},{"id":"a-abstimmung","course":"lasten","title":"Der Kranführer hat keine Sicht auf dich. Wie gibst du Anweisungen?","context":"Du bist als Anschläger eingesetzt.","answers":["Du winkst beliebig, bis eine Bewegung beginnt.","Du gibst nur einmal einen Ruf und gehst weg.","Über eindeutig vereinbarte Zeichen oder eine andere zuverlässige Verständigung."],"correct":2},{"id":"b-qualifikation","course":"bagger","title":"Was braucht eine Person für das sichere Führen eines Hydraulikbaggers im Betrieb?","context":"Eine neue Person soll Baustellenarbeiten übernehmen.","answers":["Geeignete Qualifikation, gerätebezogene Unterweisung und erforderliche Beauftragung.","Ausschließlich einen Pkw-Führerschein.","Nur eine kurze Beobachtung der Bedienung."],"correct":0},{"id":"b-pruefung","course":"bagger","title":"Was gehört zur arbeitstäglichen Maschinenkontrolle?","context":"Du übernimmst einen Bagger.","answers":["Die Lackfarbe und die Sitzpolster kontrollieren.","Sichtkontrolle und Funktionsprüfungen nach Betriebsanleitung, etwa auf Leckagen und Schäden.","Den Ausleger bei voller Geschwindigkeit bis zum Anschlag bewegen."],"correct":1},{"id":"b-leitungen","course":"bagger","title":"Was muss vor Erdarbeiten über unterirdische Leitungen bekannt sein?","context":"Du sollst einen Graben ausheben.","answers":["Nur die ungefähre Tiefe der geplanten Baugrube.","Die Farbe der oberirdischen Markierungen genügt.","Lage möglicher Leitungen klären und geeignete Sicherungs- und Erkundungsmaßnahmen festlegen."],"correct":2},{"id":"b-schwenkbereich","course":"bagger","title":"Wie schützt du Personen im Schwenkbereich des Baggers?","context":"Du hebst Material mit dem Ausleger auf.","answers":["Gefahrenbereich absperren beziehungsweise sichern und Personen fernhalten.","Vor dem Schwenken nur die Schaufel langsam bewegen.","Den Bereich über die Köpfe hinweg überfahren."],"correct":0},{"id":"b-boeschung","course":"bagger","title":"Was ist beim Arbeiten in der Nähe einer Baugrubenkante wichtig?","context":"Der Bagger steht auf gewachsenem oder aufgefülltem Boden.","answers":["Die Grabtiefe allein bestimmt die zulässige Aufstellung.","Tragfähigkeit und Sicherung der Kante sowie erforderliche Abstände nach Gefährdungsbeurteilung beachten.","So dicht wie möglich an den Rand fahren, um Reichweite zu sparen."],"correct":1},{"id":"b-standsicherheit","course":"bagger","title":"Warum sind Neigung und Untergrund beim Einsatz entscheidend?","context":"Die Baustelle liegt an einem Hang.","answers":["Die Maschine steht auf jedem Untergrund gleich stabil.","Raupenfahrwerke schließen jede Kippgefahr aus.","Unebenheiten und Gefälle können die Standsicherheit beeinflussen; Einsatzgrenzen beachten."],"correct":2},{"id":"b-wechselgeraet","course":"bagger","title":"Was prüfst du nach dem Wechsel einer Baggerschaufel über einen Schnellwechsler?","context":"Ein neues Anbaugerät wurde montiert.","answers":["Ob es entsprechend Betriebsanleitung korrekt verriegelt und gesichert ist.","Nur, ob die Schaufel farblich passt.","Ob die Hydraulik möglichst leise arbeitet."],"correct":0},{"id":"b-heben","course":"bagger","title":"Was ist beim Heben einer frei hängenden Last mit dem Bagger zu beachten?","context":"Der Bagger wird zum Hebeeinsatz verwendet.","answers":["Nur die übliche Grabkraft ist entscheidend.","Zulässige Hublast, geeignete Anschlagpunkte und vorgeschriebene Schutzeinrichtungen beachten.","Die Last kann an den Zähnen der Schaufel eingehängt werden."],"correct":1},{"id":"b-rueckwaerts","course":"bagger","title":"Du musst rückwärtsfahren, siehst aber den Fahrweg nicht. Was ist richtig?","context":"Andere Beschäftigte sind in der Nähe.","answers":["Ohne Sicht vorsichtig losfahren.","Nur hupen und weiterfahren.","Anhalten, Sicht und Gefahrenbereich sicherstellen oder eine geeignete Einweisung organisieren."],"correct":2},{"id":"b-kabel","course":"bagger","title":"Der Ausleger könnte in die Nähe einer Freileitung gelangen. Was tust du?","context":"Du arbeitest auf einer engen Baustelle.","answers":["Vorher Gefahrenbereich und geeignete Schutzmaßnahmen mit den Verantwortlichen klären.","Die Leitung ignorieren, wenn der Ausleger lackiert ist.","Den Ausleger nur besonders schnell bewegen."],"correct":0},{"id":"b-verlassen","course":"bagger","title":"Wie stellst du den Bagger vor dem Verlassen ab?","context":"Du machst eine Pause.","answers":["Den Ausleger frei schwebend stehen lassen.","Arbeitsausrüstung sicher absetzen, Maschine gegen Bewegung und unbefugte Nutzung sichern.","Den Motor laufen lassen und die Kabine offen lassen."],"correct":1},{"id":"b-hydraulik","course":"bagger","title":"Du bemerkst Hydrauliköl unter hohem Druck an einer beschädigten Leitung. Was ist richtig?","context":"Eine Leitung ist undicht.","answers":["Die Leckage mit der Hand ertasten.","Unter Druck eine neue Schelle anbringen.","Maschine sicher stillsetzen, Druck abbauen lassen und Reparatur durch befugtes Fachpersonal veranlassen."],"correct":2},{"id":"b-unterbau","course":"bagger","title":"Welche Gefahr besteht beim Befahren eines nicht tragfähigen Untergrunds?","context":"Der Boden ist nach Regen aufgeweicht.","answers":["Die Maschine kann einsinken, rutschen oder kippen.","Das Laufwerk wird automatisch breiter.","Der Schwenkbereich wird dadurch sicherer."],"correct":0},{"id":"b-arbeitsgeraet","course":"bagger","title":"Darf jemand unter einem angehobenen Arbeitsgerät arbeiten?","context":"Eine Person möchte unter der Schaufel etwas kontrollieren.","answers":["Ja, wenn der Motor im Leerlauf läuft.","Nein, nicht ohne die dafür vorgeschriebene sichere Abstützung und Sicherung der Arbeitsausrüstung.","Ja, wenn die Person einen Schutzhelm trägt."],"correct":1},{"id":"b-geraeteart","course":"bagger","title":"Du wechselst von einem Hydraulikbagger auf einen Radlader. Was ist erforderlich?","context":"Bedienung und Bewegungsverhalten sind unterschiedlich.","answers":["Nur das gleiche Schuhwerk.","Eine Probefahrt ohne Einweisung.","Die für den neuen Maschinentyp erforderliche Qualifizierung beziehungsweise Einweisung."],"correct":2},{"id":"g-neigung","course":"gabelstapler","title":"Du fährst mit einem beladenen Stapler an einer Steigung. Was ist wichtig?","context":"Die Fahrstrecke hat deutliches Gefälle.","answers":["Die Last immer talseitig führen, auch wenn sie schwer ist.","Last bergseitig führen und betriebliche Vorgaben zum Befahren von Steigungen beachten.","Unabhängig von der Fahrtrichtung die Gabel maximal hochfahren."],"correct":1},{"id":"g-gabelabsenken","course":"gabelstapler","title":"Warum muss die Gabel beim Abstellen abgesenkt werden?","context":"Der Stapler wird für eine Pause abgestellt.","answers":["Damit andere die Gabel zum Hochsteigen nutzen können.","Damit die Gabel von Weitem besser sichtbar bleibt.","Damit von der Lastaufnahme keine unnötige Stolper- oder Verletzungsgefahr ausgeht."],"correct":2},{"id":"g-fahrerwechsel","course":"gabelstapler","title":"Ein Kollege möchte den Stapler ausleihen. Was muss vorliegen?","context":"Der Kollege besitzt nur eine mündliche Erlaubnis von dir.","answers":["Er muss die erforderliche Befähigung und eine betriebliche Beauftragung besitzen.","Deine eigene Beauftragung gilt automatisch auch für ihn.","Ein privater Pkw-Führerschein genügt für jeden Betrieb."],"correct":0},{"id":"g-ladungssicherung","course":"gabelstapler","title":"Eine Palette enthält lose, übereinanderstehende Kartons. Was ist richtig?","context":"Ein Karton kann bei der Fahrt herunterfallen.","answers":["Die Last vor dem Transport gegen Verrutschen und Herabfallen sichern.","Nur auf besonders unebenem Boden langsam fahren.","Lose Kartons durch eine höhere Gabelposition ausgleichen."],"correct":0},{"id":"g-bodenbelastung","course":"gabelstapler","title":"Vor dir liegt eine Decke mit beschränkter Tragfähigkeit. Wie entscheidest du?","context":"Die Strecke führt über eine Zwischenebene.","answers":["Nur auf das Gewicht des Staplers ohne Last achten.","Die zulässige Bodenbelastung für Stapler samt Last sicher klären.","Mit Schwung fahren, damit die Decke kürzer belastet wird."],"correct":1},{"id":"g-verkehrswege","course":"gabelstapler","title":"Ein markierter Fußweg kreuzt deinen Fahrweg. Was ist richtig?","context":"Fußgänger können die Querung jederzeit betreten.","answers":["Du darfst mit der Hupe immer Vorrang beanspruchen.","Du darfst die Markierung ohne Beobachtung überfahren.","Geschwindigkeit anpassen, Fußgänger beachten und nur bei freiem Weg weiterfahren."],"correct":2},{"id":"g-parkbremse","course":"gabelstapler","title":"Du parkst einen Gabelstapler auf ebenem Gelände. Was gehört dazu?","context":"Du willst den Fahrerplatz für mehrere Minuten verlassen.","answers":["Abstellen, Parkbremse betätigen und gegen unbefugte Verwendung sichern.","Fahrzeug nur in Neutralstellung zurücklassen.","Gabel in Kopfhöhe lassen, damit sie niemand berührt."],"correct":0},{"id":"g-typenschild","course":"gabelstapler","title":"Welche Angabe ist bei der Belastung eines Staplers verbindlich?","context":"Du willst eine schwere Maschine aufnehmen.","answers":["Die geschätzte Tragkraft aus der Fahrzeuggröße.","Die Angaben des Herstellers im Last- beziehungsweise Tragfähigkeitsdiagramm.","Das Gewicht der zuletzt transportierten Palette."],"correct":1},{"id":"g-tore","course":"gabelstapler","title":"Du näherst dich mit einem Stapler einer niedrigen Durchfahrt. Was prüfst du?","context":"Auf dem Fahrzeug steht eine hoch aufragende Last.","answers":["Ob die Durchfahrt einschließlich Last und Anbaugerät sicher möglich ist.","Nur die Höhe des Gabelträgers ohne Last.","Ob du schneller hindurchfahren kannst, bevor das Tor schließt."],"correct":0},{"id":"g-reifen","course":"gabelstapler","title":"Beim täglichen Check findest du einen stark beschädigten Reifen. Was machst du?","context":"Am Reifen ist ein sicherheitsrelevanter Schaden sichtbar.","answers":["Du fährst langsam bis zum regulären Wartungstermin.","Du erhöhst den Reifendruck und fährst weiter.","Du nimmst das Fahrzeug nicht in Betrieb und meldest den Schaden."],"correct":2},{"id":"h-absperren","course":"hebebuehnen","title":"Unter deiner Arbeitsbühne gehen Beschäftigte vorbei. Was ist nötig?","context":"Es besteht Gefahr durch herabfallende Werkzeuge.","answers":["Ein geeigneter Schutz- beziehungsweise Sperrbereich unter der Arbeitsstelle.","Lediglich ein Hinweis beim ersten Vorbeigehen.","Werkzeuge möglichst weit außen am Korbrand lagern."],"correct":0},{"id":"h-werkzeuge","course":"hebebuehnen","title":"Wie transportierst du Werkzeuge im Arbeitskorb?","context":"Mehrere kleine Werkzeuge werden in der Höhe gebraucht.","answers":["Lose auf das Geländer legen, damit sie griffbereit sind.","So verstauen und sichern, dass sie nicht herunterfallen oder die Bedienung behindern.","In der Hosentasche auf der Außenseite des Geländers befestigen."],"correct":1},{"id":"h-abstuetzung","course":"hebebuehnen","title":"Eine Abstützung steht auf einem Kanaldeckel. Was ist zu prüfen?","context":"Du willst die Plattform anheben.","answers":["Nur ob der Deckel trocken ist.","Ob die Belastung an der Stelle gefahrlos aufgenommen werden kann.","Ob die anderen Stützen nicht benutzt werden müssen."],"correct":1},{"id":"h-notaus","course":"hebebuehnen","title":"Wann soll die Not-Aus-Einrichtung benutzt werden?","context":"Es entsteht unmittelbar eine gefährliche Bewegung.","answers":["Nur am Ende einer regulären Schicht.","Zum Anhalten bei akuter Gefahr gemäß Betriebsanleitung.","Als Ersatz für das planmäßige Absenken."],"correct":1},{"id":"h-schraegstellung","course":"hebebuehnen","title":"Die Neigungswarnung der Bühne spricht an. Wie reagierst du?","context":"Die Maschine steht auf einem geneigten Untergrund.","answers":["Du ignorierst die Warnung bei geringer Arbeitshöhe.","Du fährst trotz Warnung zur höchsten Hubposition.","Du stoppst, bringst die Bühne nach Herstellerangaben in einen sicheren Zustand."],"correct":2},{"id":"h-umgebung","course":"hebebuehnen","title":"Was ist beim Aufstellen nahe einer Verkehrsfläche zu organisieren?","context":"Fahrzeuge können die Bühne berühren.","answers":["Absicherung gegen Anfahren und geeignete Verkehrsführung.","Den Arbeitskorb möglichst weit über die Fahrbahn schwenken.","Nur ein Warnruf, bevor du hochfährst."],"correct":0},{"id":"h-ueberlast","course":"hebebuehnen","title":"Die Überlastwarnung im Korb wird ausgelöst. Was tust du?","context":"Zusätzliche Werkzeuge wurden eingeladen.","answers":["Mit höherer Geschwindigkeit die Arbeit beenden.","Die zulässige Korblast herstellen und die Herstellervorgaben beachten.","Das Warnsignal dauerhaft ausschalten."],"correct":1},{"id":"h-quetschen","course":"hebebuehnen","title":"Du fährst den Korb nahe unter ein Dach. Welche Gefahr ist besonders wichtig?","context":"Über dem Korb bleibt nur wenig Platz.","answers":["Einklemmen beziehungsweise Quetschen zwischen Korb und Bauwerk.","Dass der Motor mehr Kraftstoff verbraucht.","Dass die Fahrtrichtung immer automatisch umkehrt."],"correct":0},{"id":"h-stromausfall","course":"hebebuehnen","title":"Die Bühne bleibt in großer Höhe ohne Hauptantrieb stehen. Was ist richtig?","context":"Die normale Korbsteuerung reagiert nicht mehr.","answers":["Du kletterst ohne Sicherung am Ausleger hinunter.","Du wartest ohne Verständigung bis zum Schichtende.","Die vorbereitete Rettung über geschulte Personen und Notablass einleiten."],"correct":2},{"id":"h-transportstellung","course":"hebebuehnen","title":"Wie bereitest du die Bühne für einen Transport vor?","context":"Die Hubarbeitsbühne wird auf ein geeignetes Fahrzeug verladen.","answers":["Ausleger und Plattform entsprechend Betriebsanleitung in Transportstellung bringen.","Die Bühne möglichst weit ausgefahren verzurren.","Stützen ausgefahren lassen, damit sie mehr Platz beansprucht."],"correct":0},{"id":"k-bremsprobe","course":"krane","title":"Was zeigt eine Funktionsprobe der Kranbremse vor dem Einsatz?","context":"Du möchtest eine Last sicher halten können.","answers":["Ob die Bremse die Bewegung bestimmungsgemäß stoppt und hält.","Nur ob die Kabinenbeleuchtung funktioniert.","Ob der Haken automatisch eine Last aufnehmen kann."],"correct":0},{"id":"k-schraegzug","course":"krane","title":"Darfst du eine seitlich stehende Last mit dem Kran schräg ziehen?","context":"Der Haken steht nicht senkrecht über der Last.","answers":["Ja, wenn der Kran noch Tragreserve besitzt.","Nein, Lasten dürfen nicht durch unzulässigen Schrägzug gezogen werden.","Ja, wenn die Anschlagmittel besonders kurz sind."],"correct":1},{"id":"k-verhakt","course":"krane","title":"Eine Last hängt an der Unterkonstruktion fest. Was ist richtig?","context":"Beim Anheben wird Widerstand spürbar.","answers":["Du hebst weiter, bis sie sich löst.","Du bewegst die Last ruckartig seitwärts.","Du stoppst und lässt die Befestigung beziehungsweise Blockierung sicher beseitigen."],"correct":2},{"id":"k-anzuheben","course":"krane","title":"Was prüfst du beim ersten kurzen Anheben einer angeschlagenen Last?","context":"Die Last hebt wenige Zentimeter vom Boden ab.","answers":["Ob sie im Gleichgewicht hängt und die Anschlagung sicher sitzt.","Ob sich eine Person unmittelbar unter die Last stellen kann.","Ob der Kran durch schnelles Drehen stabiler wird."],"correct":0},{"id":"k-lastweg","course":"krane","title":"Wo sollte der Transportweg einer Kranlast liegen?","context":"Mehrere Arbeitsplätze befinden sich unter dem möglichen Lastweg.","answers":["Möglichst über besetzten Arbeitsplätzen.","Auf einem geplanten, freigehaltenen Weg ohne gefährdete Personen.","Immer diagonal durch den belebtesten Bereich."],"correct":1},{"id":"k-signalverlust","course":"krane","title":"Die Funkverbindung zum Einweiser bricht ab. Was tust du?","context":"Du kannst den Lastweg selbst nicht einsehen.","answers":["Du setzt die Bewegung langsam fort.","Du schwenkst probeweise in die bisherige Richtung.","Du stoppst die Bewegung, bis eine eindeutige sichere Verständigung besteht."],"correct":2},{"id":"k-haken","course":"krane","title":"Der Sicherheitshaken schließt nicht zuverlässig. Was ist richtig?","context":"Bei der Kontrolle fällt ein defekter Verschluss auf.","answers":["Der Fehler muss vor weiterer Benutzung fachgerecht behoben werden.","Du bindest den Verschluss mit einem Kabelbinder fest.","Du benutzt den Haken nur bei leichten Lasten."],"correct":0},{"id":"k-zugrichtung","course":"krane","title":"Was ist für die senkrechte Aufnahme einer Last wichtig?","context":"Die Last soll aus einer Maschine gehoben werden.","answers":["Der Kranhaken sollte über dem Lastschwerpunkt ausgerichtet sein.","Der Haken soll möglichst seitlich angeordnet sein.","Die Last muss vor dem Heben angeschoben werden."],"correct":0},{"id":"k-wartung","course":"krane","title":"Am Kran fällt ein ungewohntes Schleifgeräusch auf. Wie gehst du vor?","context":"Das Geräusch tritt beim Heben auf.","answers":["Die Geräuschentwicklung durch höhere Geschwindigkeit überdecken.","Den Betrieb sicher stoppen, Mangel melden und klären lassen.","Bis zur Pause ohne Hinweis weiterarbeiten."],"correct":1},{"id":"k-absetzen","course":"krane","title":"Was muss beim Absetzen einer Kranlast gewährleistet sein?","context":"Eine schwere Last wird auf einer Unterlage positioniert.","answers":["Die Last darf ungesichert auf einer schrägen Fläche liegen.","Anschlagmittel werden entfernt, solange sie noch schwebt.","Die Last steht stabil und ist gegen Kippen oder Wegrollen gesichert."],"correct":2},{"id":"l-schwerpunkt","course":"lasten","title":"Warum muss der Schwerpunkt vor dem Anschlagen bekannt sein?","context":"Eine asymmetrisch geformte Maschine soll transportiert werden.","answers":["Damit die Last beim Anheben möglichst im Gleichgewicht bleibt.","Damit die Anschlagmittel beliebig lang gewählt werden können.","Damit die zulässige Tragfähigkeit keine Rolle spielt."],"correct":0},{"id":"l-etikett","course":"lasten","title":"Ein Hebeband hat kein lesbares Tragfähigkeitsetikett. Was ist richtig?","context":"Die Kennzeichnung ist unkenntlich geworden.","answers":["Die Tragfähigkeit anhand der Farbe schätzen.","Das Hebeband nicht benutzen, bis die Eignung eindeutig nachgewiesen ist.","Das Band nur einmal für kleine Lasten einsetzen."],"correct":1},{"id":"l-kantenschutz","course":"lasten","title":"Ein Textilband liegt über einer scharfen Stahlkante. Was ist nötig?","context":"Die Last weist scharfe Kanten auf.","answers":["Das Band möglichst stramm ungeschützt ziehen.","Den Hub schneller durchführen.","Geeigneten Kantenschutz oder ein anderes passendes Anschlagmittel einsetzen."],"correct":2},{"id":"l-spreizwinkel","course":"lasten","title":"Wie beeinflusst ein größerer Neigungswinkel die Belastung von Anschlagsträngen?","context":"Eine Last wird mit zwei schrägen Strängen gehoben.","answers":["Bei ungünstigeren Winkeln können die Kräfte in den Strängen zunehmen.","Die Strangkräfte verschwinden.","Der Winkel hat keinen Einfluss auf die Beanspruchung."],"correct":0},{"id":"l-knoten","course":"lasten","title":"Darf ein Anschlagseil durch einen Knoten beliebig verkürzt werden?","context":"Das Seil ist für die geplante Last zu lang.","answers":["Ja, ein fester Knoten verbessert die Tragfähigkeit.","Nein, nur zugelassene Verkürzungs- und Anschlagverfahren verwenden.","Ja, wenn der Knoten mit Klebeband gesichert wird."],"correct":1},{"id":"l-zeichen","course":"lasten","title":"Was gilt für die Kommunikation mit der kranführenden Person?","context":"Der Lastweg ist teilweise verdeckt.","answers":["Mehrere Personen geben gleichzeitig unterschiedliche Zeichen.","Es werden eindeutige, zuvor vereinbarte Signale genutzt.","Eine Kommunikation ist bei Funkkranen nie erforderlich."],"correct":1},{"id":"l-sichtpruefung","course":"lasten","title":"Wann sind Anschlagmittel auf erkennbare Mängel zu kontrollieren?","context":"Du willst eine Anschlagkette einsetzen.","answers":["Vor der Verwendung auf äußerlich erkennbare Schäden achten.","Nur wenn bereits ein Unfall passiert ist.","Nur einmal bei der erstmaligen Anschaffung."],"correct":0},{"id":"l-drehung","course":"lasten","title":"Eine angehobene Last beginnt sich unkontrolliert zu drehen. Was machst du?","context":"Die Last bewegt sich im Lastweg.","answers":["Du greifst mit der Hand zwischen Last und Wand.","Du stellst dich unter die Last und hältst sie fest.","Du hältst Abstand und lässt die Bewegung kontrolliert stoppen."],"correct":2},{"id":"l-ablegen","course":"lasten","title":"Wann dürfen Anschlagmittel von der Last gelöst werden?","context":"Die Last wird auf Böcken abgesetzt.","answers":["Wenn die Last stabil steht und gegen Umstürzen oder Wegrollen gesichert ist.","Sobald sie den Boden erstmals berührt, unabhängig von ihrer Lage.","Noch während des Schwebens, um Zeit zu sparen."],"correct":0},{"id":"l-ketten","course":"lasten","title":"Eine Anschlagkette weist ein stark verbogenes Glied auf. Was tust du?","context":"Der Schaden ist schon vor dem Heben sichtbar.","answers":["Die beschädigte Stelle mit Draht umwickeln.","Die Kette aus dem Einsatz nehmen und fachgerecht prüfen lassen.","Die Last nur halb so hoch anheben."],"correct":1},{"id":"b-einweiser","course":"bagger","title":"Was ist bei eingeschränkter Sicht aus dem Bagger wichtig?","context":"Ein Gebäudeteil verdeckt den Fahrbereich.","answers":["Geeignete Sichtmaßnahmen beziehungsweise Einweisung und klare Verständigung.","Nur die Motorhaube beobachten.","Den Schwenkbereich trotz Unsichtbarkeit befahren."],"correct":0},{"id":"b-aushub","course":"bagger","title":"Wo darf Aushubmaterial nahe einer Baugrube gelagert werden?","context":"Die Grubenkante darf nicht zusätzlich gefährdet werden.","answers":["Direkt an der Kante aufschütten, damit Fahrwege frei bleiben.","Mit ausreichend sicherem Abstand und nach Baustellenvorgaben lagern.","Auf losem Verbau ohne weitere Prüfung ablegen."],"correct":1},{"id":"b-personen","course":"bagger","title":"Dürfen Personen während der Baggerbewegung im Schwenkbereich bleiben?","context":"Eine Person möchte während des Schwenkens messen.","answers":["Ja, solange sie einen Schutzhelm trägt.","Ja, wenn der Bagger langsam schwenkt.","Nein, der Gefahrenbereich muss vor der Bewegung frei sein."],"correct":2},{"id":"b-ladung","course":"bagger","title":"Wie transportierst du Material mit einem Radlader sicher?","context":"Eine gefüllte Schaufel soll über den Hof gefahren werden.","answers":["Mit geeigneter niedriger Transportstellung und freiem Fahrweg.","Mit hochgehobener Schaufel für bessere Fernsicht.","Mit offenen Türen und starkem Lenkeinschlag."],"correct":0},{"id":"b-anbaupruefung","course":"bagger","title":"Was kontrollierst du nach dem Ankoppeln eines Anbaugeräts?","context":"Eine neue Schaufel wurde befestigt.","answers":["Nur die Sauberkeit der Lackierung.","Die sichere Verriegelung und Funktion gemäß Betriebsanleitung.","Nur ob das Gerät von außen gleich aussieht."],"correct":1},{"id":"b-einstieg","course":"bagger","title":"Wie steigst du sicher in die Baggerkabine ein?","context":"Die Trittstufen sind nach Regen verschmutzt.","answers":["Über den Ausleger auf die Kabine klettern.","Mit einem Sprung auf die Raupen steigen.","Vorgesehene Aufstiege und Haltegriffe nutzen und verschmutzte Tritte reinigen."],"correct":2},{"id":"b-graben","course":"bagger","title":"Eine Grabenwand zeigt Risse und bröckelt. Was ist richtig?","context":"Du arbeitest unmittelbar neben dem Graben.","answers":["Arbeit stoppen und Sicherung der Baugrube durch Verantwortliche veranlassen.","Einfach näher an die Kante fahren, um den Graben zu schließen.","Den Graben ohne Absicherung weiter vertiefen."],"correct":0},{"id":"b-betanken","course":"bagger","title":"Was beachtest du beim Betanken einer Erdbaumaschine?","context":"Der Tank ist beinahe leer.","answers":["Motor und Zündquellen nach Herstellervorgaben sichern und Verschütten vermeiden.","Benzin oder Diesel stets in der Kabine umfüllen.","Während des Betankens rauchen, wenn kein Wind weht."],"correct":0},{"id":"b-laufwerk","course":"bagger","title":"Warum müssen Raupen und Laufwerk regelmäßig kontrolliert werden?","context":"Du bemerkst ungewöhnliche Vibrationen beim Fahren.","answers":["Damit die Maschine schneller fahren kann.","Weil Schäden die sichere Führung und Standsicherheit beeinträchtigen können.","Weil der Arbeitseinsatz ohne Sichtprüfung immer zulässig ist."],"correct":1},{"id":"b-einweisen","course":"bagger","title":"Was ist bei Arbeiten nahe öffentlichem Fußgängerverkehr erforderlich?","context":"Ein Bagger arbeitet direkt an einer Gehwegkante.","answers":["Fußgänger sollen sich selbst durch den Schwenkbereich bewegen.","Nur ein Schild an die Schaufel kleben.","Gefahrenbereich wirksam absperren und Verkehr sicher führen."],"correct":2},{"id":"g2-fahrweg","course":"gabelstapler","title":"Vor dir liegt verschüttete Flüssigkeit auf dem Fahrweg. Wie gehst du vor?","context":"Der Stapler würde unmittelbar über den rutschigen Bereich fahren.","answers":["Fahrt anhalten und Gefahrenstelle sichern oder beseitigen lassen.","Die Stelle bei angehobener Gabel möglichst schnell überfahren.","Auf trockenere Reifen hoffen und unverändert weiterfahren."],"correct":0},{"id":"g2-sichtladung","course":"gabelstapler","title":"Eine hohe Palette versperrt die Sicht nach vorn. Was ist richtig?","context":"Du musst zu einem Lagerplatz fahren und kannst den Fahrweg nicht einsehen.","answers":["Die Palette hochheben, bis du unter ihr hindurchsehen kannst.","Nur nach geeigneter sicherer Methode fahren, beispielsweise rückwärts mit freier Sicht.","Den Fahrweg ohne Einweiser oder freie Sicht trotzdem befahren."],"correct":1},{"id":"g2-fussgaengerstop","course":"gabelstapler","title":"Ein Fußgänger bleibt unmittelbar neben dem Stapler stehen. Was tust du?","context":"Die Person befindet sich im möglichen Fahr- und Schwenkbereich.","answers":["Den Fußgänger durch kurzes Beschleunigen überholen.","Mit angehobener Last an der Person vorbeifahren.","Anhalten und erst mit sicherem Abstand weiterfahren."],"correct":2},{"id":"g2-hubmast","course":"gabelstapler","title":"Am Hubmast bemerkst du eine beschädigte Hydraulikleitung. Was gilt?","context":"Hydrauliköl tritt sichtbar aus dem Arbeitsgerät aus.","answers":["Stapler außer Betrieb nehmen und den Schaden melden.","Die undichte Stelle während des Hebens mit der Hand prüfen.","Nur kleinere Lasten heben, bis die Schicht zu Ende ist."],"correct":0},{"id":"g2-lagerregal","course":"gabelstapler","title":"Du willst eine Palette in ein Regal einlagern. Was prüfst du zuerst?","context":"Die Regalebene ist hoch und die Tragfähigkeit muss eingehalten werden.","answers":["Die Palette möglichst schnell in das Regal schieben.","Regalfach, Lastgewicht und freie Einlagerungsfläche auf Eignung prüfen.","Das Gesamtgewicht allein nach der Kartonanzahl schätzen."],"correct":1},{"id":"g2-batterieschaden","course":"gabelstapler","title":"Eine Staplerbatterie ist äußerlich beschädigt. Was ist richtig?","context":"Vor dem Laden fallen Risse oder ungewöhnliche Flüssigkeit auf.","answers":["Beschädigung mit Klebeband abdecken und sofort laden.","Die Batterie ohne Prüfung durch eine andere Person laden lassen.","Nicht laden oder benutzen und zuständige Fachpersonen informieren."],"correct":2},{"id":"g2-fahrerkabine","course":"gabelstapler","title":"Was gilt für lose Gegenstände im Fahrerbereich?","context":"Werkzeug liegt auf dem Boden neben den Bedienpedalen.","answers":["Gegenstände entfernen und den Bedienbereich frei halten.","Werkzeug nur mit einem Fuß während der Fahrt festhalten.","Lose Teile unter dem Fahrersitz verstecken."],"correct":0},{"id":"g2-uebergabe","course":"gabelstapler","title":"Du übernimmst einen Stapler nach einem Schichtwechsel. Was gehört dazu?","context":"Ein Kollege hat das Fahrzeug zuletzt verwendet.","answers":["Annehmen, dass der Kollege sämtliche Prüfungen übernommen hat.","Erforderliche Prüfung durchführen und bekannte Mängel erfragen.","Ohne Blick auf die Maschine die Fahrt beginnen."],"correct":1},{"id":"g2-transportsicherung","course":"gabelstapler","title":"Ein hoher Gegenstand steht lose auf der Palette. Wie handelst du?","context":"Die Last könnte beim Bremsen nach vorn kippen.","answers":["Die Gabel besonders hoch tragen, damit die Last stabil bleibt.","Nur die Kurven langsam nehmen, geradeaus schneller fahren.","Last standsicher aufbauen und gegen Umfallen oder Herabfallen sichern."],"correct":2},{"id":"g2-arbeitsende","course":"gabelstapler","title":"Was ist bei einem unbeaufsichtigten Stapler wichtig?","context":"Du beendest deine Schicht und verlässt den Bereich.","answers":["Fahrzeug sicher abstellen, gegen Wegrollen und unbefugte Nutzung sichern.","Schlüssel stecken lassen, damit Kollegen die Maschine finden.","Gabel auf Augenhöhe belassen, damit sie sichtbar ist."],"correct":0},{"id":"g2-bremsweg","course":"gabelstapler","title":"Warum musst du mit Last den Bremsweg besonders beachten?","context":"Der Stapler transportiert schwere Ware durch einen Lagergang.","answers":["Mit schwerer Last stets später bremsen als ohne Last.","Geschwindigkeit den Sicht-, Untergrund- und Lastverhältnissen anpassen.","Beim Bremsen die Last stark anheben, um besser zu verzögern."],"correct":1},{"id":"g2-rampe","course":"gabelstapler","title":"Was prüfst du vor dem Befahren einer steilen Rampe?","context":"Die Route ist für das Fahrzeug möglicherweise zu steil.","answers":["Die Rampe unabhängig vom Gefälle mit Maximalgeschwindigkeit befahren.","Mit angehobener Last über den Rampenrand fahren.","Zulässige Steigung und sichere Betriebsweise aus der Fahrzeugvorgabe prüfen."],"correct":2},{"id":"g2-zinke","course":"gabelstapler","title":"Eine Palette ist breiter als der Gabelabstand. Was ist zu beachten?","context":"Du planst die Aufnahme einer ungewöhnlich großen Ladung.","answers":["Gabelabstand und Aufnahmepunkte passend zur Last einstellen.","Nur eine Zinke benutzen, wenn die Last zu breit ist.","Die Ladung schräg anheben, bis sie die richtige Lage erreicht."],"correct":0},{"id":"g2-betriebsanweisung","course":"gabelstapler","title":"Welche Rolle spielt die betriebliche Verkehrsregelung?","context":"Im Lager gelten markierte Einbahn- und Fußgängerbereiche.","answers":["Mit Staplern gelten nur die Regeln der öffentlichen Straße.","Die vorgegebenen Fahrwege und Verkehrsregeln beachten.","Markierungen ignorieren, sobald das Fahrzeug beladen ist."],"correct":1},{"id":"g2-nothalt","course":"gabelstapler","title":"Die Lenkung reagiert während der Fahrt ungewöhnlich. Was ist richtig?","context":"Das Fahrzeug lässt sich nicht mehr gewohnt kontrollieren.","answers":["Mit höherer Geschwindigkeit fahren, damit die Lenkung leichter reagiert.","Den Fehler durch besonders große Lenkausschläge ausgleichen.","An sicherer Stelle anhalten und Fahrzeug prüfen lassen."],"correct":2},{"id":"g2-anschlagkette","course":"gabelstapler","title":"Du willst mit einem Stapler eine frei hängende Last bewegen. Was gilt?","context":"Eine Last soll an einem Haken unter den Gabeln hängen.","answers":["Nur mit dafür freigegebenem Gerät und geeigneter Lastaufnahmeeinrichtung.","Eine beliebige Kette reicht aus, wenn die Last nicht schwer ist.","Die Kette direkt zwischen beide Gabelzinken klemmen."],"correct":0},{"id":"g2-rollenlast","course":"gabelstapler","title":"Ein zylindrisches Bauteil liegt ungesichert auf einer Palette. Was tust du?","context":"Die Ladung kann während des Transports rollen.","answers":["Mit der Palette besonders ruckartig anfahren.","Bauteil gegen Rollen sichern, bevor die Palette aufgenommen wird.","Die Zinken so hoch stellen, dass das Bauteil nicht sichtbar ist."],"correct":1},{"id":"g2-pruefplakette","course":"gabelstapler","title":"Woran erkennst du, ob der Stapler eingesetzt werden darf?","context":"An der Maschine klebt eine Prüfplakette.","answers":["Eine beliebige Plakette ersetzt immer die tägliche Sichtprüfung.","Eine fehlende Freigabe kann durch vorsichtige Fahrweise ersetzt werden.","Neben der Prüfung des Fahrzeugs sind gültiger Prüfstatus und Einsatzfreigabe zu beachten."],"correct":2},{"id":"g2-licht","course":"gabelstapler","title":"Im Lager ist die Beleuchtung plötzlich ausgefallen. Was ist richtig?","context":"Du kannst Hindernisse im Fahrweg nicht mehr sicher erkennen.","answers":["Fahrt unterbrechen, bis sichere Sicht gewährleistet ist.","Die Fahrgeschwindigkeit erhöhen, um den dunklen Bereich zu verlassen.","Mit angehobener Gabel ohne Sichtkontrolle weiterfahren."],"correct":0},{"id":"g2-ueberhang","course":"gabelstapler","title":"Eine Last ragt seitlich weit über die Gabel hinaus. Was prüfst du?","context":"Du willst die Palette durch ein schmales Tor transportieren.","answers":["Die seitliche Ausladung durch eine schnelle Kurve ausgleichen.","Freiraum, Stabilität und zulässige Lastaufnahme vor der Fahrt beurteilen.","Die Last unabhängig von ihrer Form mit Maximaltempo fahren."],"correct":1},{"id":"g2-wartungsbereich","course":"gabelstapler","title":"Vor einem Wartungsbereich stehen Absperrungen. Wie verhältst du dich?","context":"Dein üblicher Fahrweg ist vorübergehend gesperrt.","answers":["Absperrungen kurz verschieben und unbemerkt hindurchfahren.","Unter Last direkt durch den Arbeitsbereich fahren.","Sperrung beachten und eine freigegebene alternative Strecke wählen."],"correct":2},{"id":"g2-bremsprobe","course":"gabelstapler","title":"Wann ist eine Funktionsprüfung der Betriebsbremse sinnvoll?","context":"Du bereitest den Stapler vor der Arbeit vor.","answers":["Im Rahmen der vorgeschriebenen Prüfung vor dem Einsatz.","Ausschließlich nach einem schweren Unfall durchführen.","Nur wenn der Stapler bereits eine hohe Geschwindigkeit erreicht hat."],"correct":0},{"id":"g2-fahrzeuganhaenger","course":"gabelstapler","title":"Du möchtest einen Anhänger mit dem Stapler ziehen. Was ist erforderlich?","context":"Der Betrieb plant einen Transport mit angehängter Last.","answers":["Jeden Anhänger ohne Prüfung an eine Gabelzinke binden.","Herstellerfreigabe, geeignete Kupplung und zulässige Zuglast beachten.","Nur den Reifendruck erhöhen und losfahren."],"correct":1},{"id":"g2-rueckfahrt","course":"gabelstapler","title":"Was ist beim Rückwärtsfahren mit dem Stapler wichtig?","context":"Im Lagergang befindet sich ein unübersichtlicher Bereich.","answers":["Dauerhaft nur in den Rückspiegel sehen, unabhängig von der Umgebung.","Ohne Sicht fahren, solange die Hupe einmal betätigt wurde.","Fahrweg und Personenbereich sicher beobachten und nötigenfalls einweisen lassen."],"correct":2},{"id":"g2-lastentnahme","course":"gabelstapler","title":"Du entnimmst eine Palette aus einem hohen Regalfach. Was ist richtig?","context":"Die Palette steht möglicherweise nicht mittig.","answers":["Last sicher aufnehmen und vor dem Absenken stabilisieren.","Die Palette beim Herausziehen zur Seite schwenken lassen.","Unterhalb der angehobenen Palette nachsehen, ob sie beschädigt ist."],"correct":0},{"id":"h2-absenkweg","course":"hebebuehnen","title":"Warum muss der Bereich unter einer Hubarbeitsbühne frei bleiben?","context":"Der Korb wird abgesenkt und unter ihm stehen Materialien.","answers":["Materialien mit dem Korb nach unten drücken.","Nur den Fußbereich der Bedienperson im Auge behalten.","Quetsch- und Kollisionsgefahren beim Absenken vermeiden."],"correct":2},{"id":"h2-transporthoehe","course":"hebebuehnen","title":"Wie verfährst du eine fahrbare Bühne über einen niedrigen Durchgang?","context":"Die Durchfahrt ist niedriger als der ausgefahrene Ausleger.","answers":["Bühne gemäß Betriebsanleitung in geeignete Transportstellung bringen.","Ausleger ausgefahren lassen und unter der Decke entlangfahren.","Den Korb seitlich an den Türrahmen drücken."],"correct":0},{"id":"h2-bodenoeffnung","course":"hebebuehnen","title":"Neben der Bühne ist eine ungesicherte Bodenöffnung. Wie reagierst du?","context":"Ein Fahr- oder Abstützpunkt liegt in der Nähe der Öffnung.","answers":["Eine Abstützung direkt auf den Rand der Öffnung setzen.","Aufstellort wechseln oder die Tragfähigkeit und Sicherung fachgerecht klären.","Die Gefahrenstelle nur durch einen Karton verdecken."],"correct":1},{"id":"h2-rettungsperson","course":"hebebuehnen","title":"Warum muss eine zweite Person mit dem Rettungsverfahren vertraut sein?","context":"Eine Bedienperson könnte oben handlungsunfähig werden.","answers":["Damit Arbeiten im Korb grundsätzlich ohne Sicherung stattfinden dürfen.","Damit die Bühne schneller als zugelassen betrieben werden darf.","Damit im Notfall eine sichere Rettung eingeleitet werden kann."],"correct":2},{"id":"h2-werkzeugabwurf","course":"hebebuehnen","title":"Was gilt für Werkzeuge in großer Höhe?","context":"Ein loses Werkzeug könnte über die Korbkante fallen.","answers":["Werkzeuge so sichern, dass sie niemanden gefährden oder herabfallen.","Werkzeuge zur Entlastung einfach auf dem Geländer abstellen.","Werkzeuge bei Bedarf aus dem Korb nach unten werfen."],"correct":0},{"id":"h2-trittstufe","course":"hebebuehnen","title":"Eine Kiste soll als zusätzliche Standfläche im Korb dienen. Was ist richtig?","context":"Du erreichst die Arbeitsstelle sonst nur knapp.","answers":["Die Kiste auf das Geländer stellen und darauf klettern.","Nicht auf improvisierte Erhöhungen steigen; geeignetes Arbeitsmittel einsetzen.","Den Korb absichtlich über die zulässige Höhe hinaus belasten."],"correct":1},{"id":"h2-lastverteilen","course":"hebebuehnen","title":"Worauf achtest du bei mehreren Personen im Arbeitskorb?","context":"Im Korb arbeiten zwei Personen mit schwerem Werkzeug.","answers":["Die Last ausschließlich nach der Werkzeuggröße beurteilen.","Schweres Werkzeug direkt auf dem Schutzgeländer lagern.","Zulässige Korblast einschließlich Personen und Werkzeug nicht überschreiten."],"correct":2},{"id":"h2-abstuetzplatte","course":"hebebuehnen","title":"Wann kommen zusätzliche Unterlegplatten für Stützen in Betracht?","context":"Der Aufstellboden ist nur begrenzt belastbar.","answers":["Wenn dies zur sicheren Lastverteilung nach Vorgaben erforderlich ist.","Um die Stützen möglichst dicht am Rand einer Baugrube aufzulegen.","Um ohne Herstellerangaben beliebig größere Reichweiten zu nutzen."],"correct":0},{"id":"h2-baugrube","course":"hebebuehnen","title":"Eine Bühne soll direkt an einer Baugrubenkante stehen. Was prüfst du?","context":"Der Untergrund könnte durch die Baugrube seitlich nachgeben.","answers":["Die Stützen in die Baugrube hinein verlängern.","Ausreichenden Sicherheitsabstand und Tragfähigkeit des Untergrunds sicherstellen.","Das Risiko nur durch langsames Heben des Korbs ausgleichen."],"correct":1},{"id":"h2-witterung","course":"hebebuehnen","title":"Während des Einsatzes setzt Vereisung ein. Wie handelst du?","context":"Bedienflächen und Arbeitsbereich werden glatt.","answers":["Die Bühne höher fahren, um Schnee und Eis zu vermeiden.","Die Warnhinweise ignorieren, solange die Plattform beleuchtet ist.","Arbeiten unterbrechen und Einsatzbedingungen gemäß Betriebsanleitung neu bewerten."],"correct":2},{"id":"h2-aufbaukontakt","course":"hebebuehnen","title":"Eine Stahlkonstruktion schränkt den Korbweg ein. Was ist wichtig?","context":"Beim Anheben droht eine Quetschung zwischen Korb und Träger.","answers":["Bewegungen so planen, dass Körper und Korb nicht eingeklemmt werden.","Die Fahrt schneller ausführen, damit der Korb rascher vorbeikommt.","Die Konstruktion mit dem Korb zur Seite drücken."],"correct":0},{"id":"h2-sicherheitsabstand","course":"hebebuehnen","title":"Wann muss der Gefahrenbereich einer Bühne abgesperrt werden?","context":"Unter dem Einsatzort führt ein öffentlicher Verkehrsweg vorbei.","answers":["Nur wenn bereits ein Gegenstand heruntergefallen ist.","Wenn Dritte durch Bewegung oder herabfallende Gegenstände gefährdet werden könnten.","Niemals, da der Arbeitskorb grundsätzlich alle Gefahren verhindert."],"correct":1},{"id":"h2-korbtor","course":"hebebuehnen","title":"Was gilt für die Einstiegstür des Arbeitskorbs?","context":"Du bist bereits auf Arbeitshöhe.","answers":["Die Tür offen lassen, damit man schneller aussteigen kann.","Die Tür durch ein Seil dauerhaft offen binden.","Die Tür entsprechend der vorgesehenen Verriegelung geschlossen halten."],"correct":2},{"id":"h2-energieleitung","course":"hebebuehnen","title":"Was gilt, wenn eine Freileitung nicht sicher abgeschaltet ist?","context":"Du arbeitest mit der Hubarbeitsbühne in ihrer Nähe.","answers":["Vorgegebene Sicherheitsabstände und notwendige Schutzmaßnahmen sicherstellen.","Den Korb bis kurz vor die Leitung bewegen, solange sie nicht berührt wird.","Auf die Kunststoffreifen vertrauen und ohne Abstand arbeiten."],"correct":0},{"id":"h2-schwanken","course":"hebebuehnen","title":"Der Arbeitskorb beginnt ungewöhnlich stark zu schwingen. Was ist richtig?","context":"Der Bewegungsverlauf ist nicht mehr kontrolliert.","answers":["Mit schnellen Gegenbewegungen unkontrolliert nachregeln.","Bewegung stoppen und Ursache beziehungsweise Einsatzbedingungen prüfen.","Zusätzliche Personen in den Korb holen, um ihn schwerer zu machen."],"correct":1},{"id":"h2-ladegeraet","course":"hebebuehnen","title":"Ein Ladekabel der elektrisch betriebenen Bühne ist beschädigt. Was tust du?","context":"Beim Anschließen ist eine beschädigte Isolierung sichtbar.","answers":["Den Schaden mit nassen Handschuhen anfassen.","Den Stecker möglichst stark in die Buchse drücken.","Ladevorgang nicht starten und das Kabel fachgerecht prüfen lassen."],"correct":2},{"id":"h2-gelaenderanbau","course":"hebebuehnen","title":"Darfst du ein Geländer eigenständig entfernen, um näher heranzukommen?","context":"Ein Bauteil verhindert die Annäherung an die Arbeitsstelle.","answers":["Schutzeinrichtungen nicht eigenmächtig verändern oder entfernen.","Das Geländer nach dem Anheben abschrauben und später montieren.","Ohne Geländer weiterarbeiten, solange eine Person danebensteht."],"correct":0},{"id":"h2-lastkran","course":"hebebuehnen","title":"Darf die Bühne als Kran zum Heben einer Last verwendet werden?","context":"Material soll frei hängend neben dem Arbeitskorb transportiert werden.","answers":["Immer, wenn das Gewicht kleiner als das eigene Körpergewicht ist.","Nur wenn Hersteller und Ausrüstung diesen besonderen Einsatz ausdrücklich zulassen.","Einfach einen Haken am Geländer befestigen und Material anheben."],"correct":1},{"id":"h2-arbeitsvorbereitung","course":"hebebuehnen","title":"Was gehört zur Vorbereitung an einem neuen Einsatzort?","context":"Du kennst den Baustellenbereich noch nicht.","answers":["Nur die Entfernung zum nächsten Parkplatz schätzen.","Unabhängig von der Umgebung sofort ganz ausfahren.","Gefährdungen, Boden, Verkehrswege, Rettung und Gerätetauglichkeit beurteilen."],"correct":2},{"id":"h2-kabelschlaufe","course":"hebebuehnen","title":"Ein Stromkabel liegt quer über dem Fahrweg der Bühne. Was ist richtig?","context":"Beim Verfahren könnte das Kabel eingeklemmt werden.","answers":["Fahrweg frei machen und elektrische Leitungen vor Beschädigung schützen.","Das Kabel mit den Rädern als Fahrbahnschwelle nutzen.","Den Korb hochfahren, ohne den Bodenbereich zu kontrollieren."],"correct":0},{"id":"h2-leitungsnaehe","course":"hebebuehnen","title":"Wer klärt die Schutzmaßnahmen an einer elektrischen Anlage?","context":"Die Bühne soll nahe an unter Spannung stehenden Betriebsmitteln arbeiten.","answers":["Die Person im Korb entscheidet allein nach Augenmaß.","Zuständige Stellen einbeziehen und abgestimmte Schutzmaßnahmen umsetzen.","Der Abstand wird erst nach Beginn der Arbeit festgelegt."],"correct":1},{"id":"h2-funkkommunikation","course":"hebebuehnen","title":"Warum müssen Signale zwischen Boden und Korb eindeutig sein?","context":"Eine Person am Boden unterstützt das Rangieren.","answers":["Damit mehrere Personen gleichzeitig widersprüchliche Anweisungen geben können.","Damit der Notablass ohne Einweisung ausprobiert wird.","Damit Bewegungen nur nach klarer Verständigung ausgeführt werden."],"correct":2},{"id":"h2-neuebedienung","course":"hebebuehnen","title":"Du wechselst auf eine andere Bauart von Bühne. Was ist erforderlich?","context":"Die Bedienfunktionen unterscheiden sich deutlich.","answers":["Eine gerätespezifische Einweisung vor dem selbstständigen Einsatz.","Nur das Lesen des Firmenlogos auf dem Gerät.","Eine Probefahrt mit bereits ausgefahrenem Korb ohne Anleitung."],"correct":0},{"id":"h2-steckanschluss","course":"hebebuehnen","title":"Was ist vor dem Anschluss eines Ladegeräts zu prüfen?","context":"Eine elektrische Hubarbeitsbühne soll aufgeladen werden.","answers":["Jede Steckdose unabhängig von Zustand und Absicherung verwenden.","Geeigneten Anschluss und unbeschädigte Leitung gemäß Herstellerangaben prüfen.","Den Netzstecker während des Ladevorgangs regelmäßig herausziehen."],"correct":1},{"id":"h2-absperrpersonal","course":"hebebuehnen","title":"Eine Person betritt während der Hubarbeit den abgesperrten Bereich. Was tust du?","context":"Du erkennst eine Person direkt unter dem Arbeitskorb.","answers":["Weiterfahren, wenn die Person einen Schutzhelm trägt.","Ein Werkzeug als Warnsignal in ihre Richtung fallen lassen.","Gefährdende Bewegung unterbrechen und den Bereich räumen lassen."],"correct":2},{"id":"k2-arbeitsplanung","course":"krane","title":"Was gehört vor einem Kraneinsatz zur Arbeitsvorbereitung?","context":"Last, Standort und Transportweg sind noch nicht abgestimmt.","answers":["Zuerst die schwerste Last ohne weitere Planung anheben.","Nur den kürzesten Weg auf dem Hallenboden markieren.","Tragfähigkeit, Anschlagmittel, Lastweg und Gefahrenbereich vorab klären."],"correct":2},{"id":"k2-hakenposition","course":"krane","title":"Wie wird der Kranhaken vor dem Anheben über der Last positioniert?","context":"Die Anschlagpunkte liegen unterhalb des Krans.","answers":["Möglichst senkrecht über dem Lastschwerpunkt entsprechend der Anschlagung.","Weit seitlich versetzt, damit die Last schneller einschwenkt.","In jedem Fall am äußeren Rand der Last, unabhängig vom Schwerpunkt."],"correct":0},{"id":"k2-hakengabel","course":"krane","title":"Ein Lasthaken zeigt eine auffällige Verformung. Was gilt?","context":"Der Haken sieht gegenüber seinem üblichen Zustand aufgebogen aus.","answers":["Die Verformung mit der nächsten Last zurückbiegen.","Kranbetrieb unterbrechen und den Haken fachkundig überprüfen lassen.","Nur noch leichte Lasten anhängen und weiterarbeiten."],"correct":1},{"id":"k2-zugueberlast","course":"krane","title":"Die Last ist schwerer als zunächst angenommen. Was tust du?","context":"Bei der Vorbereitung ergeben sich neue Gewichtsangaben.","answers":["Die Sicherheitsreserve durch schnelleres Heben ersetzen.","Das Lastgewicht durch Anschlagen an einem anderen Punkt ignorieren.","Tatsächliche Last bestimmen und Tragfähigkeitsgrenzen erneut prüfen."],"correct":2},{"id":"k2-arbeitskorb","course":"krane","title":"Darf ein gewöhnlicher Kranhaken ohne Weiteres Personen befördern?","context":"Eine Person möchte an eine hoch gelegene Arbeitsstelle gelangen.","answers":["Nein, Personentransport erfordert dafür zulässige besondere Einrichtungen und Maßnahmen.","Ja, wenn sich die Person am Anschlagseil festhält.","Ja, sobald der Hub besonders langsam ausgeführt wird."],"correct":0},{"id":"k2-bruecke","course":"krane","title":"Ein Brückenkran fährt auf einem gemeinsam genutzten Hallenweg. Was ist wichtig?","context":"Unter dem Transportweg halten sich Beschäftigte auf.","answers":["Mit der Last knapp über den Köpfen der Beschäftigten fahren.","Lastweg und Verkehrsbereich wirksam freihalten beziehungsweise absichern.","Nur die Warnhupe statt weiterer Maßnahmen benutzen."],"correct":1},{"id":"k2-zweitekrane","course":"krane","title":"Zwei Krane arbeiten in einem überschneidenden Bereich. Was ist notwendig?","context":"Ausleger oder Lasten könnten miteinander kollidieren.","answers":["Beide Kranführer arbeiten ohne Absprache gleichzeitig.","Die Bewegungen werden bewusst beschleunigt, um Kreuzungen zu vermeiden.","Einsätze koordinieren und geeignete Maßnahmen gegen gegenseitige Gefährdung treffen."],"correct":2},{"id":"k2-pruefbuch","course":"krane","title":"Welche Bedeutung hat die vorgeschriebene wiederkehrende Kranprüfung?","context":"Die Maschine wird regelmäßig im Betrieb eingesetzt.","answers":["Sie ergänzt die Betriebskontrolle durch die vorgeschriebene fachkundige Prüfung.","Sie ersetzt jede Sichtprüfung vor Arbeitsbeginn dauerhaft.","Sie ist nur nach einem Absturz erforderlich."],"correct":0},{"id":"k2-absetzflaeche","course":"krane","title":"Die vorgesehene Absetzfläche ist uneben. Wie handelst du?","context":"Die Last könnte beim Aufsetzen kippen.","answers":["Last auf einer Ecke absetzen und unverändert hängen lassen.","Geeignete tragfähige und stabile Unterlagen beziehungsweise Fläche vorbereiten.","Eine Person während des Absetzens unter die Last stellen."],"correct":1},{"id":"k2-anfahrbereich","course":"krane","title":"Vor dem Anfahren des Krans befindet sich eine Person im Fahrbereich. Was tust du?","context":"Der Fahrweg ist durch eine Person blockiert.","answers":["Die Person durch eine kleine Probefahrt zur Seite drängen.","Ohne Sichtkontrolle allein anhand des Endschalters anfahren.","Bewegung erst starten, wenn der Gefahrenbereich frei und sicher ist."],"correct":2},{"id":"k2-schlaffseil","course":"krane","title":"Warum darf das Hubseil beim Absetzen nicht unkontrolliert schlaff werden?","context":"Die Last liegt auf, der Haken wird weiter abgesenkt.","answers":["Damit Seil und Haken nicht verklemmen oder unkontrolliert belastet werden.","Damit die Last anschließend durch das Seil seitlich gezogen werden kann.","Damit sich Anschlagmittel selbstständig vom Haken lösen."],"correct":0},{"id":"k2-pendel","course":"krane","title":"Eine transportierte Last gerät ins Pendeln. Was ist richtig?","context":"Die Last bewegt sich seitlich stärker als geplant.","answers":["Mit schnellen Gegenbewegungen und voller Fahrt kompensieren.","Bewegungen kontrolliert reduzieren und Pendeln ohne Personen im Gefahrenbereich beruhigen.","Die schwingende Last mit bloßen Händen festhalten."],"correct":1},{"id":"k2-funkakku","course":"krane","title":"Die Funksteuerung eines Krans hat eine schwache Batterie. Was gilt?","context":"Die Verbindung könnte während des Hebens abbrechen.","answers":["Noch schnell eine Last heben, bevor die Steuerung ausfällt.","Bei Verbindungsverlust die Last durch Ziehen am Anschlagmittel bewegen.","Vor dem Einsatz eine zuverlässige Steuerverbindung sicherstellen."],"correct":2},{"id":"k2-mehrereanschlaeger","course":"krane","title":"Zwei Personen geben dem Kranführer gleichzeitig unterschiedliche Zeichen. Was ist richtig?","context":"Die Zeichen widersprechen einander.","answers":["Bewegung unterbrechen und eindeutige Zuständigkeit klären.","Das Zeichen der weiter entfernten Person bevorzugen.","Die Bewegung nach eigenem Gefühl fortsetzen."],"correct":0},{"id":"k2-endabschaltung","course":"krane","title":"Warum darf eine Endabschaltung nicht als normale Hubbegrenzung missbraucht werden?","context":"Die Last wird häufig bis zum maximalen Hubweg bewegt.","answers":["Endschalter erlauben grundsätzlich schnelleres Heben ohne Sicht.","Endschalter sind Sicherheitseinrichtungen und ersetzen keine kontrollierte Bedienung.","Sie sollen bei jedem Hub möglichst hart angefahren werden."],"correct":1},{"id":"k2-wetterbeobachtung","course":"krane","title":"Der Wind nimmt bei einer großflächigen Last deutlich zu. Was ist erforderlich?","context":"Eine große Bauteilfläche wirkt wie ein Segel.","answers":["Die Last immer höher heben, damit der Wind weniger wirkt.","Die Anschlagmittel durch dünnere ersetzen.","Wind- und Einsatzgrenzen beurteilen und gegebenenfalls das Heben einstellen."],"correct":2},{"id":"k2-ortswechsel","course":"krane","title":"Was ist beim Versetzen eines Mobilkrans an einen neuen Standort wichtig?","context":"Untergrund und Stützbedingungen verändern sich.","answers":["Standplatz und Abstützung vor erneuter Lastaufnahme prüfen.","Die Einstellungen des vorherigen Standorts ungeprüft übernehmen.","Die Abstützung während des Hebens nachjustieren lassen."],"correct":0},{"id":"k2-betriebsbereich","course":"krane","title":"Ein Kran soll über eine Straße hinweg arbeiten. Was ist zu klären?","context":"Dritte könnten in den Gefahrenbereich gelangen.","answers":["Die Fahrbahn nur mit einer Warnhupe sichern.","Erforderliche Sperrungen, Abstimmungen und Schutzmaßnahmen vor dem Hub.","Die Last ohne Sicherung möglichst schnell über Fahrzeuge heben."],"correct":1},{"id":"k2-hochheben","course":"krane","title":"Nach dem Probehub hängt eine Last deutlich schief. Was ist richtig?","context":"Der Schwerpunkt wurde offenbar falsch eingeschätzt.","answers":["Weiterheben, damit sich die Schieflage von selbst ausgleicht.","Eine Person an der schiefen Last ziehen lassen.","Last sicher absetzen und Anschlagung sowie Schwerpunkt erneut prüfen."],"correct":2},{"id":"k2-schwebelast","course":"krane","title":"Darfst du eine angehobene Last unbeaufsichtigt hängen lassen?","context":"Die Schicht endet, aber die Last hängt noch am Haken.","answers":["Nein, Last sicher absetzen und Kran ordnungsgemäß sichern.","Ja, wenn der Kran gegen Wegfahren verriegelt wird.","Ja, sofern ein Warnschild am Boden steht."],"correct":0},{"id":"k2-mitnahme","course":"krane","title":"Ein Kollege möchte auf einer Kranlast mitfahren. Was gilt?","context":"Die Last soll zu einem höher gelegenen Punkt transportiert werden.","answers":["Mitfahren ist zulässig, wenn der Kollege einen Helm trägt.","Personen dürfen nicht auf oder an gewöhnlichen Lasten mitbefördert werden.","Mitfahren ist immer erlaubt, sobald der Kollege dem Kranführer bekannt ist."],"correct":1},{"id":"k2-warnsignal","course":"krane","title":"Eine betriebliche Warnanlage am Kran fällt aus. Was ist richtig?","context":"Vor dem Anfahren ist kein vorgesehener Warnhinweis mehr möglich.","answers":["Die Anlage ignorieren, wenn der Motor läuft.","Die Warnung dauerhaft durch Klopfen auf das Gehäuse ersetzen.","Sicherheitsrelevanten Ausfall melden und Betrieb gemäß Vorgaben unterbrechen."],"correct":2},{"id":"k2-schneekante","course":"krane","title":"Ein Autokran soll auf gefrorenem unebenem Boden abgestützt werden. Was gilt?","context":"Der Boden kann beim Auftauen an Tragfähigkeit verlieren.","answers":["Tragfähigkeit und Stützsituation unter den tatsächlichen Bedingungen beurteilen.","Gefrorener Boden ist immer beliebig tragfähig.","Stützen ausschließlich auf kleine Steine stellen."],"correct":0},{"id":"k2-laufkatze","course":"krane","title":"Eine Laufkatze fährt auf ein Hindernis zu. Wie handelst du?","context":"Im Fahrbereich steht ein Gegenstand.","answers":["Den Gegenstand mit der Last langsam wegdrücken.","Bewegung rechtzeitig stoppen und Hindernis sicher beseitigen lassen.","Mit erhöhter Geschwindigkeit am Hindernis vorbeifahren."],"correct":1},{"id":"k2-anschlagaufnahme","course":"krane","title":"Du sollst eine Last an einer nicht ausgewiesenen Öse aufnehmen. Was ist richtig?","context":"Die Öse könnte nur zur Montage einer Abdeckung bestimmt sein.","answers":["Jede Öse ist für volle Krantraglast geeignet.","Die Öse nur mit zwei Personen gleichzeitig belasten.","Tragfähigkeit und Eignung des Anschlagpunkts vor Benutzung verifizieren."],"correct":2},{"id":"l2-seilbruch","course":"lasten","title":"Ein Drahtseil zeigt mehrere gebrochene Einzeldrähte. Was ist richtig?","context":"Die Bruchstellen liegen im tragenden Seilbereich.","answers":["Anschlagmittel nicht weiterbenutzen und fachgerecht beurteilen lassen.","Die Drahtenden mit bloßen Händen zurückbiegen.","Das Seil weiterverwenden, wenn die Last besonders leicht ist."],"correct":0},{"id":"l2-schaekel","course":"lasten","title":"Was ist bei der Verwendung eines Schäkels entscheidend?","context":"Ein Schäkel verbindet Anschlagmittel und Last.","answers":["Den Bolzen durch einen beliebigen Nagel ersetzen.","Geeignete Tragfähigkeit, unbeschädigten Zustand und ordnungsgemäßen Bolzen prüfen.","Die Tragfähigkeit anhand der Farbe abschätzen."],"correct":1},{"id":"l2-tragfaehigkeit","course":"lasten","title":"Was musst du bei einer mehrsträngigen Anschlagung beachten?","context":"Die Stränge verlaufen schräg zur Senkrechten.","answers":["Die Tragfähigkeit jedes Strangs einfach beliebig addieren.","Die Last ausschließlich am leichtesten Strang einhängen.","Tragfähigkeit der gesamten Anschlagart und Winkel berücksichtigen."],"correct":2},{"id":"l2-schweissnaht","course":"lasten","title":"Darf ein improvisierter Anschlagpunkt an eine Last geschweißt werden?","context":"Für die Last fehlen geeignete ausgewiesene Aufnahmepunkte.","answers":["Nur fachgerecht ausgelegte und freigegebene Anschlagpunkte verwenden.","Eine beliebige Schweißnaht genügt ohne Prüfung.","Einen Haken durch eine Öffnung im Blech stecken."],"correct":0},{"id":"l2-einseitig","course":"lasten","title":"Eine Last ist auf einer Seite deutlich schwerer. Wie gehst du vor?","context":"Der Schwerpunkt liegt außerhalb der geometrischen Mitte.","answers":["Alle Stränge unabhängig vom Schwerpunkt gleich lang lassen.","Schwerpunkt ermitteln und Anschlagung darauf abstimmen.","Die Last zuerst bis zur vollen Hubhöhe anheben."],"correct":1},{"id":"l2-kettenriss","course":"lasten","title":"Was gilt für eine Anschlagkette mit sichtbaren Rissen?","context":"An einem Kettenglied fällt ein Riss auf.","answers":["Den Riss mit Farbe markieren und unverändert heben.","Das Glied mit Draht umwickeln und weiterverwenden.","Kette sofort aussondern und zuständige Person informieren."],"correct":2},{"id":"l2-lastfuehrung","course":"lasten","title":"Wie führst du eine große Last bei Drehgefahr?","context":"Die Last kann während des Anhebens seitlich ausschwenken.","answers":["Geeignete vorgesehene Führungsmittel und sicheren Abstand benutzen.","Die Last während der Fahrt direkt zwischen den Händen halten.","Unter die Last treten und sie von unten ausrichten."],"correct":0},{"id":"l2-schnueren","course":"lasten","title":"Was ist bei der Schnürgang-Anschlagung wichtig?","context":"Das Anschlagmittel wird um ein Bauteil geführt.","answers":["Die gleiche Tragfähigkeit wie bei jeder anderen Anschlagart annehmen.","Eignung der Anschlagart und zulässige Belastung gemäß Kennzeichnung beachten.","Das Anschlagmittel ungeprüft beliebig stark zusammenziehen."],"correct":1},{"id":"l2-winkelmesser","course":"lasten","title":"Warum darfst du einen flachen Strangwinkel nicht ignorieren?","context":"Zwei Anschlagstränge laufen nahezu waagerecht zur Last.","answers":["Ein flacher Winkel macht den Strang automatisch stärker.","Die Last verteilt sich unabhängig vom Winkel stets gleich.","Hohe Strangkräfte können die zulässige Tragfähigkeit überschreiten."],"correct":2},{"id":"l2-heisse-last","course":"lasten","title":"Was musst du bei einer heißen Last prüfen?","context":"Ein Stahlteil wurde kurz zuvor wärmebehandelt.","answers":["Temperaturgrenzen der Anschlagmittel und geeignete Auswahl beachten.","Jedes textile Anschlagmittel verträgt beliebige Temperaturen.","Die Kennzeichnung spielt bei Hitze keine Rolle."],"correct":0},{"id":"l2-abstand","course":"lasten","title":"Darfst du beim Absetzen mit den Fingern unter die Last greifen?","context":"Die Last soll millimetergenau auf einer Unterlage landen.","answers":["Ja, wenn du Arbeitshandschuhe trägst.","Nein, Abstand halten und geeignete Hilfsmittel verwenden.","Ja, wenn die Kranbewegung besonders langsam ist."],"correct":1},{"id":"l2-verbindung","course":"lasten","title":"Ein Verbindungsglied der Anschlagkette ist nicht verriegelt. Was gilt?","context":"Die Sicherung des Verbindungselements fehlt.","answers":["Den Bolzen ohne Verriegelung benutzen, sofern niemand zusieht.","Das Element mit Klebeband verschließen.","Nicht anschlagen, bis das Verbindungselement korrekt gesichert ist."],"correct":2},{"id":"l2-lasthaken","course":"lasten","title":"Was prüfst du beim Einhängen in einen Kranhaken?","context":"Mehrere Anschlagmittel sollen in den Haken geführt werden.","answers":["Sicheren Sitz und Eignung von Haken und Aufhängung sicherstellen.","Anschlagmittel an der Hakenspitze auflegen.","Die Hakensicherung durch einen Kabelbinder ersetzen."],"correct":0},{"id":"l2-fasern","course":"lasten","title":"Ein Hebeband zeigt starke Aufrauhung und Faserschäden. Was ist richtig?","context":"Tragende Fasern sind sichtbar beschädigt.","answers":["Mit einem weiteren Knoten die Schäden verdecken.","Hebeband aussondern und fachkundig überprüfen lassen.","Die Last anschließend schneller anheben."],"correct":1},{"id":"l2-anheben","course":"lasten","title":"Was gilt unmittelbar beim ersten Zentimeter des Anhebens?","context":"Die Last hebt gerade von ihrer Unterlage ab.","answers":["Die Last ohne Kontrolle bis zur vollen Höhe ziehen.","Unter der Last schauen, ob die Anschlagmittel gespannt sind.","Sitz der Anschlagung, Gleichgewicht und Bewegungsverhalten prüfen."],"correct":2},{"id":"l2-lastgewichte","course":"lasten","title":"Das Lastgewicht ist unbekannt. Was ist richtig?","context":"Das Bauteil besitzt keine Gewichtskennzeichnung.","answers":["Belastbares Gewicht ermitteln, bevor Anschlagmittel ausgewählt werden.","Das Gewicht anhand der Farbe der Last schätzen.","Ein beliebiges Anschlagmittel mit doppelter Länge verwenden."],"correct":0},{"id":"l2-lose-teile","course":"lasten","title":"Auf der zu hebenden Last liegen lose Werkzeuge. Was tust du?","context":"Beim Anheben könnten Werkzeuge herunterfallen.","answers":["Werkzeuge bei der Fahrt mit einer Hand auffangen.","Lose Gegenstände vor dem Hub entfernen oder wirksam sichern.","Die Last etwas schneller anheben, damit nichts verrutscht."],"correct":1},{"id":"l2-wind","course":"lasten","title":"Eine großflächige Last wird bei starkem Wind angeschlagen. Was gilt?","context":"Das Bauteil bietet dem Wind eine große Angriffsfläche.","answers":["Die Last ohne Rücksicht auf Pendelbewegungen anheben.","Zusätzliche Personen sollen die Last direkt festhalten.","Windverhältnisse beurteilen und bei unsicherer Lage den Hub unterlassen."],"correct":2},{"id":"l2-unterlage","course":"lasten","title":"Warum sind geeignete Unterlagen beim Absetzen wichtig?","context":"Eine runde Last würde auf dem Boden wegrollen.","answers":["Last standsicher absetzen und gegebenenfalls gegen Rollen sichern.","Die Last direkt auf den Anschlagmitteln stehen lassen.","Die Unterlagen erst nach dem Absetzen unter die Last schieben."],"correct":0},{"id":"l2-transportweg","course":"lasten","title":"Was muss vor dem Lasttransport abgestimmt werden?","context":"Die Last wird über mehrere Arbeitsbereiche bewegt.","answers":["Nur die voraussichtliche Dauer des Hubs.","Sicherer Lastweg, Verständigung und notwendige Absperrungen.","Eine Person soll unter der Last den Weg anzeigen."],"correct":1},{"id":"l2-schutzschlauch","course":"lasten","title":"Was ist bei Anschlagmitteln mit Schutzschlauch zu beachten?","context":"Ein Band liegt an einer rauen Kante an.","answers":["Jeder dünne Stofflappen ersetzt einen geeigneten Kantenschutz.","Ein Schutzschlauch hebt jede zulässige Belastungsgrenze auf.","Schutzmittel entsprechend Eignung und Einsatzvorgaben auswählen."],"correct":2},{"id":"l2-reinigung","course":"lasten","title":"Ein Hebeband wurde mit unbekannter Chemikalie verschmutzt. Was ist richtig?","context":"Das Band ist nicht mehr eindeutig zu beurteilen.","answers":["Benutzung stoppen und Verträglichkeit beziehungsweise Zustand fachgerecht klären.","Mit beliebigem Lösungsmittel reinigen und sofort weiterheben.","Die Chemikalie ignorieren, solange das Band trocken ist."],"correct":0},{"id":"l2-aufhaengung","course":"lasten","title":"Was prüfst du bei mehreren Strängen am Aufhängeglied?","context":"Zwei Stränge werden gemeinsam in eine Aufhängung gelegt.","answers":["Ein Strang darf beliebig in die Hakenspitze ausweichen.","Alle Verbindungselemente müssen geeignet und bestimmungsgemäß angeordnet sein.","Ein Ring mit Riss kann bei kleinen Lasten verwendet werden."],"correct":1},{"id":"l2-einweiserrolle","course":"lasten","title":"Was gilt, wenn Anschläger und Kranführer keine Sichtverbindung haben?","context":"Ein Träger versperrt die Sicht auf den Absetzpunkt.","answers":["Durch Zuruf mehrerer Personen ohne Zuständigkeit koordinieren.","Die Last ohne Einweisung anhand von Geräuschen bewegen.","Eindeutige sichere Kommunikation organisieren und bei Unklarheit stoppen."],"correct":2},{"id":"l2-ausserbetrieb","course":"lasten","title":"Ein beschädigtes Anschlagmittel wurde aussortiert. Was ist zusätzlich wichtig?","context":"Es liegt weiterhin frei zugänglich neben einsatzbereiten Mitteln.","answers":["Gegen erneute versehentliche Verwendung sichern und zuständige Person informieren.","Das Mittel unmarkiert in den Bestand zurücklegen.","Es nur bei einer besonders leichten Last noch einmal benutzen."],"correct":0},{"id":"b2-schwenkradius","course":"bagger","title":"Warum ist der hintere Schwenkradius eines Baggers kritisch?","context":"Das Heck bewegt sich über eine begrenzte Arbeitsfläche.","answers":["Dritte können vom schwenkenden Oberwagen erfasst werden.","Der Schwenkradius hat keinen Einfluss auf Personen neben der Maschine.","Das Heck bewegt sich immer nur in Fahrtrichtung."],"correct":0},{"id":"b2-verkehrseinweiser","course":"bagger","title":"Wie wird eine Fahrbewegung bei verdeckter Sicht abgesichert?","context":"Ein Bagger soll hinter einem Hindernis rangieren.","answers":["Ohne Sicht auf die Signale des Einweisers fahren.","Bei Bedarf geeignete Einweisung mit klarer Verständigung organisieren.","Die Rückwärtsfahrt nur durch einmaliges Hupen absichern."],"correct":1},{"i